struct EDGE { int v,w,c,nx; }edge_list[N<<1]; int edge_count=1,head_list[N];
void connect (int u,int v,int w,int c)
{
    edge_list[++edge_count]=(EDGE){v,w,c,head_list[u]},head_list[u]=edge_count;
    edge_list[++edge_count]=(EDGE){u,0,-c,head_list[v]},head_list[v]=edge_count;
