int source,sink;
int dist[N],flow[N],pre[N],las[N]; bool in_q[N];
bool bellman_ford()
{
    for (int i=1; i<=sink; i++)
        dist[i]=1e9, flow[i]=pre[i]=las[i]=0, in_q[i]=0;
    queue<int> q; dist[source]=0; flow[source]=1e9; q.push(source); in_q[source]=1;
    while (!q.empty())
